nativeAbort.script:
import { spawn } from "node:child_process";
const root = process.cwd();
const child = spawn(process.env.AGDA, ["--interaction-json", "--no-libraries", "-i", root], { cwd: root, env: { ...process.env, AGDA_DIR: root + "/.agda-dir" } });
const t0 = performance.now(); let out = "";
child.stdout.setEncoding("utf8");
child.stdout.on("data", (d) => { out += d; for (const l of d.split("\n")) if (l) process.stdout.write(`[${Math.round(performance.now()-t0)}ms] ${l.slice(0,160)}\n`); });
child.stderr.on("data", (d) => process.stdout.write(`[stderr ${JSON.stringify(String(d))}]\n`));
child.on("exit", (code, sig) => console.log("exit", code, sig, Math.round(performance.now()-t0)));
const f = JSON.stringify(root + "/Slow.agda");
let deep = "z"; for (let i = 0; i < 40; i++) deep = `(s ${deep})`;
const cmds = [
  `IOTCM ${f} NonInteractive Direct (Cmd_load ${f} [])`,
  `IOTCM ${f} None Direct (Cmd_compute_toplevel DefaultCompute "slow ${deep}")`,
  `IOTCM ${f} None Direct (Cmd_goal_type_context Normalised 0 noRange "")`,
];
let i = 0, prompts = 0;
const send = () => { if (i < cmds.length) { console.log(">>> " + cmds[i].slice(0, 120)); child.stdin.write(cmds[i++] + "\n"); if (i === 2) setTimeout(() => { console.log(">>> abort"); child.stdin.write(`IOTCM ${f} None Direct Cmd_abort\n`); }, 500); } else child.stdin.end(); };
child.stdout.on("data", () => { const n = (out.match(/(^|\n)JSON> /g) || []).length; while (prompts < n) { prompts++; send(); } });

page.script:
// A scratch drive of the real page: hover, case split, refine, STOP, PLFA.
const repo = "<repository>";
const cdp = await import(repo + "/scripts/browser-check/cdp.mjs");
const { serve } = await import(repo + "/scripts/browser-check/serve.mjs");
const SOURCE = `module Main where

open import Agda.Builtin.Nat

f : Nat → Nat
f n = {! n !}

g : Nat → Nat
g n = {! !}
`;
const server = await serve({ root: repo + "/build" });
const chrome = await cdp.launch(process.env.CHROME);
const page = chrome.page;
const log = [];
await page.onConsole((e) => log.push(e));
await page.setViewport(1440, 900);
await page.addInitScript(`localStorage.setItem("agda-web-ide-beta:doc", ${JSON.stringify(SOURCE)});`);
await page.navigate(`${server.origin}/`);
const state = () => ({
  status: document.querySelector(".inspector-status")?.textContent?.trim() ?? "",
  bar: [...document.querySelectorAll(".statusbar > span")].map((s) => s.textContent?.replace(/\s+/g, " ").trim()).join(" | "),
  busy: document.querySelector(".spin") !== null,
  goals: [...document.querySelectorAll(".goal-card .goal-number")].map((g) => g.textContent?.trim()),
  goalTypes: [...document.querySelectorAll(".goal-card code")].map((g) => g.textContent?.trim()),
  context: [...document.querySelectorAll(".context-row")].map((r) => r.textContent?.replace(/\s+/g, " ").trim()),
  problems: [...document.querySelectorAll(".problem-card pre")].map((p) => p.textContent),
  result: document.querySelector(".result-card pre")?.textContent ?? null,
  editor: [...document.querySelectorAll(".cm-content .cm-line")].map((l) => l.textContent),
  minibuffer: document.querySelector("#command-input") !== null,
  tooltip: document.querySelector(".cm-tooltip")?.textContent ?? null,
  failed: document.querySelector(".action-error span")?.textContent ?? null,
  banner: document.querySelector(".fatal-banner")?.textContent ?? null,
});
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
async function waitFor(pred, what, ms = 120000) {
  const t0 = performance.now(); let s;
  while (performance.now() - t0 < ms) { s = await page.eval(state); if (s.banner) throw new Error(s.banner); if (pred(s)) return s; await sleep(100); }
  throw new Error(`timeout: ${what}: ${JSON.stringify(s)}`);
}
const click = (title) => page.eval((title) => { const b = [...document.querySelectorAll("button")].find((b) => b.getAttribute("title")?.startsWith(title)); if (!b || b.disabled) throw new Error("no " + title); b.click(); }, title);
const submit = (value) => page.eval((value) => { const i = document.querySelector("#command-input"); i.value = value; i.dispatchEvent(new Event("input", { bubbles: true })); i.form.requestSubmit(); }, value);
const out = {};
try {
  let s = await waitFor((s) => / · \d/.test(s.status) && !s.busy, "first check");
  out.first = { status: s.status, goals: s.goals, types: s.goalTypes };
  // Hover over "Nat" on line 5.
  const rect = await page.eval(() => {
    const line = [...document.querySelectorAll(".cm-line")].find((l) => l.textContent.startsWith("f : Nat"));
    const walker = document.createTreeWalker(line, NodeFilter.SHOW_TEXT);
    let node; while ((node = walker.nextNode())) { const i = node.textContent.indexOf("Nat"); if (i >= 0) { const r = document.createRange(); r.setStart(node, i); r.setEnd(node, i + 2); const b = r.getBoundingClientRect(); return { x: b.left + b.width / 2, y: b.top + b.height / 2 }; } }
  });
  await page.send("Input.dispatchMouseEvent", { type: "mouseMoved", x: rect.x, y: rect.y });
  s = await waitFor((s) => s.tooltip, "a hover tooltip", 20000).catch((e) => ({ tooltip: `none (${e.message.slice(0, 80)})` }));
  out.hover = s.tooltip;
  await page.send("Input.dispatchMouseEvent", { type: "mouseMoved", x: 5, y: 5 });
  // Case split goal 0 on n.
  await page.eval(() => [...document.querySelectorAll(".goal-card")][0].click());
  await waitFor((s) => !s.busy, "goal 0 selected");
  await click("Case split");
  await waitFor((s) => s.minibuffer, "case minibuffer");
  await submit("n");
  s = await waitFor((s) => !s.busy && !s.minibuffer && s.editor.some((l) => l.startsWith("f zero")), "the case split");
  out.caseSplit = s.editor.filter((l) => l.startsWith("f "));
  // Check: three goals.
  await page.eval(() => document.querySelector(".cm-content").focus());
  await page.press("Enter", "Enter", 13, 2);
  s = await waitFor((s) => !s.busy && / · \d/.test(s.status) && s.goals.length === 3, "the check after the split");
  out.afterSplit = { status: s.status, goals: s.goals, types: s.goalTypes };
  // Refine the last goal with suc.
  await page.eval(() => [...document.querySelectorAll(".goal-card")].at(-1).click());
  await waitFor((s) => !s.busy, "last goal selected");
  await click("Refine");
  await waitFor((s) => s.minibuffer, "refine minibuffer");
  await submit("suc");
  s = await waitFor((s) => !s.busy && !s.minibuffer && s.editor.some((l) => l.startsWith("g n = suc")), "the refine");
  out.refine = s.editor.filter((l) => l.startsWith("g "));
  // Fast give: type a term inside the remaining goal and check.
  await page.eval(() => document.querySelector(".cm-content").focus());
  // PLFA, STOP, then a whole check.
  await page.eval(() => [...document.querySelectorAll(".chapter-row")].find((r) => r.textContent.includes("Naturals")).click());
  await waitFor((s) => s.editor.some((l) => l.includes("module plfa.part1.Naturals")), "the chapter in the editor");
  // The chapter's interface archives mount first; a check waits for them.
  await sleep(500);
  await waitFor((s) => !s.busy, "the chapter's archives", 60000);
  await page.eval(() => document.querySelector(".cm-content").focus());
  await page.press("Enter", "Enter", 13, 2);
  const t1 = performance.now();
  for (;;) { if (await page.eval(() => document.querySelector(".abort-action") !== null)) break; if (performance.now() - t1 > 30000) throw new Error("no STOP"); await sleep(50); }
  await sleep(1000);
  const before = await page.eval(state);
  await page.eval(() => document.querySelector(".abort-action").click());
  const t0 = performance.now();
  s = await waitFor((s) => !s.busy, "the abort", 30000);
  out.abort = { busyBefore: before.busy, statusBefore: before.status, ms: Math.round(performance.now() - t0), status: s.status, bar: s.bar, failed: s.failed };
  await page.eval(() => document.querySelector(".cm-content").focus());
  await page.press("Enter", "Enter", 13, 2);
  s = await waitFor((s) => !s.busy && / · \d/.test(s.status), "the chapter's check", 180000);
  out.plfa = { status: s.status, goals: s.goals.length, problems: s.problems.length, bar: s.bar };
} catch (e) { out.error = e.message; }
out.exceptions = log.filter((e) => e.type === "exception" || e.type === "error").map((e) => e.text).slice(0, 10);
console.log(JSON.stringify(out, null, 1));
await chrome.close(); await server.close();

