  bar: [...document.querySelectorAll(".statusbar > span")].map((s) => s.textContent?.replace(/\s+/g, " ").trim()).join(" | "),
  busy: document.querySelector(".spin") !== null,
  goals: [...document.querySelectorAll(".goal-card .goal-number")].map((g) => g.textContent?.trim()),
  goalTypes: [...document.querySelectorAll(".goal-card code")].map((g) => g.textContent?.trim()),
  context: [...document.querySelectorAll(".context-row")].map((r) => r.textContent?.replace(/\s+/g, " ").trim()),
