  result: document.querySelector(".result-card pre")?.textContent ?? null,
  editor: [...document.querySelectorAll(".cm-content .cm-line")].map((l) => l.textContent),
  minibuffer: document.querySelector("#command-input") !== null,
  tooltip: document.querySelector(".cm-tooltip")?.textContent ?? null,
  failed: document.querySelector(".action-error span")?.textContent ?? null,
  banner: document.querySelector(".fatal-banner")?.textContent ?? null,
});
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
async function waitFor(pred, what, ms = 120000) {
  const t0 = performance.now(); let s;
  while (performance.now() - t0 < ms) { s = await page.eval(state); if (s.banner) throw new Error(s.banner); if (pred(s)) return s; await sleep(100); }
  throw new Error(`timeout: ${what}: ${JSON.stringify(s)}`);
}
const click = (title) => page.eval((title) => { const b = [...document.querySelectorAll("button")].find((b) => b.getAttribute("title")?.startsWith(title)); if (!b || b.disabled) throw new Error("no " + title); b.click(); }, title);
const submit = (value) => page.eval((value) => { const i = document.querySelector("#command-input"); i.value = value; i.dispatchEvent(new Event("input", { bubbles: true })); i.form.requestSubmit(); }, value);
const out = {};
try {
  let s = await waitFor((s) => / · \d/.test(s.status) && !s.busy, "first check");
  out.first = { status: s.status, goals: s.goals, types: s.goalTypes };
  // 1. Case split h's goal on m, inside the where block.
  await page.eval(() => [...document.querySelectorAll(".goal-card")][0].click());
  await waitFor((s) => !s.busy, "goal 0 selected");
  await click("Case split");
  await waitFor((s) => s.minibuffer, "case minibuffer");
  await submit("m");
  s = await waitFor((s) => !s.busy && !s.minibuffer && s.editor.some((l) => l.includes("h zero")), "the case split");
  out.caseSplit = s.editor.filter((l) => l.includes("h "));
  await page.eval(() => document.querySelector(".cm-content").focus());
  await page.press("Enter", "Enter", 13, 2);
  s = await waitFor((s) => !s.busy && / · \d/.test(s.status) && s.goals.length === 3, "the check after the split");
  out.afterSplit = { status: s.status, goals: s.goals, problems: s.problems };
  // 2. Open a chapter without checking it, and infer _+_ there.
  await page.eval(() => [...document.querySelectorAll(".chapter-row")].find((r) => r.textContent.includes("Naturals")).click());
  await waitFor((s) => s.editor.some((l) => l.includes("module plfa.part1.Naturals")), "the chapter in the editor");
  await sleep(500);
  await waitFor((s) => !s.busy, "the chapter's archives", 60000);
  const t0 = performance.now();
  await click("Infer type");
  await waitFor((s) => s.minibuffer, "infer minibuffer");
  await submit("_+_");
  s = await waitFor((s) => !s.busy && !s.minibuffer && s.result !== null, "the inference", 180000);
  out.infer = { ms: Math.round(performance.now() - t0), result: s.result, status: s.status, failed: s.failed, problems: s.problems.length };
  // 3. Back to the playground: the check it runs must load, not say "Already checked".
  await page.eval(() => [...document.querySelectorAll(".file-row")].find((r) => r.textContent.includes("Main.agda")).click());
  s = await waitFor((s) => !s.busy && s.editor.some((l) => l.includes("module Main")) && s.goals.length > 0, "the playground's check", 60000);
  out.back = { status: s.status, bar: s.bar, goals: s.goals, marked: await page.eval(() => document.querySelectorAll(".cm-content [class*='agda']").length) };
} catch (e) { out.error = e.message; }
out.exceptions = log.filter((e) => e.type === "exception" || e.type === "error").map((e) => e.text).slice(0, 10);
console.log(JSON.stringify(out, null, 1));
await chrome.close(); await server.close();

